// An explicit user-started, ordinary Windows installation check. No elevation,
// no ACL changes, no scheduled tasks, no /QA and no alternate user-data profile.
using System;using System.IO;using System.Linq;using System.Text;using System.Net;
using System.Diagnostics;using System.Collections;using System.Collections.Generic;
using System.Security.Cryptography;using System.Text.RegularExpressions;using System.Threading;
using System.Windows.Forms;using System.Drawing;using System.Web.Script.Serialization;
using System.Runtime.InteropServices;using Microsoft.Win32;
[assembly:System.Reflection.AssemblyTitle("Motivelium — проверка установки Windows")]
[assembly:System.Reflection.AssemblyVersion("0.1.0.3")]
namespace MotiveliumInstallerCheck {
 static class Entry {
  [STAThread] static int Main(string[] args){
   if(args.Length>0&&args[0]=="--self-test")return Checks.SelfTest(args.Length>1?args[1]:null);
   Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
   Application.Run(new CheckWindow());return 0;
  }
 }
 sealed class CheckWindow:Form {
  readonly Button start=new Button(),stop=new Button();readonly TextBox log=new TextBox();readonly Label status=new Label();bool busy;Checks check;
  public CheckWindow(){Text="Motivelium — проверка установки Windows";ClientSize=new Size(810,620);MinimumSize=new Size(740,560);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(243,241,235);Font=new Font("Segoe UI",10);
   var title=new Label{Text="Проверка без повышения прав",Font=new Font("Segoe UI",21,FontStyle.Bold),AutoSize=true,Location=new Point(26,22)};Controls.Add(title);
   var details=new Label{Text="alpha.1 → запуск через «Пуск» → проект → обновление до alpha.2 → удаление → повторная установка.\nМожно повторить на точной установке из прошлого прогона. Все проекты сохраняются. Чужую или изменённую установку проверка не заменяет.",Location=new Point(28,77),Size=new Size(748,80),Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right};Controls.Add(details);
   status.Text="Откройте двойным щелчком из Проводника. Не выбирайте «Запуск от имени администратора».";status.Location=new Point(28,165);status.Size=new Size(750,42);status.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right;Controls.Add(status);
   log.Location=new Point(28,216);log.Size=new Size(750,320);log.Multiline=true;log.ReadOnly=true;log.ScrollBars=ScrollBars.Vertical;log.BackColor=Color.White;log.Anchor=AnchorStyles.Top|AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right;Controls.Add(log);
   start.Text="Начать проверку";start.Location=new Point(28,556);start.Size=new Size(220,38);start.Anchor=AnchorStyles.Bottom|AnchorStyles.Left;start.BackColor=Color.FromArgb(54,95,78);start.ForeColor=Color.White;Controls.Add(start);
   stop.Text="Остановить после шага";stop.Location=new Point(265,556);stop.Size=new Size(220,38);stop.Anchor=AnchorStyles.Bottom|AnchorStyles.Left;stop.Enabled=false;Controls.Add(stop);
   start.Click+=(s,e)=>Begin();stop.Click+=(s,e)=>{if(check!=null)check.Cancel=true;stop.Enabled=false;status.Text="Остановлю проверку после текущего действия.";};
   FormClosing+=(s,e)=>{if(busy){e.Cancel=true;if(check!=null)check.Cancel=true;status.Text="Проверка останавливается после текущего действия. Проекты не удаляются.";}};
  }
  void ShowProgress(string text){if(IsDisposed)return;BeginInvoke((Action)(()=>{status.Text=text;log.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+text+Environment.NewLine);}));}
  void Begin(){if(busy)return;busy=true;start.Enabled=false;stop.Enabled=true;check=new Checks(AppDomain.CurrentDomain.BaseDirectory,ShowProgress);var thread=new Thread(()=>{bool ok=check.Run();BeginInvoke((Action)(()=>{busy=false;stop.Enabled=false;start.Text="Проверка завершена";status.Text=ok?"Пройдено. Проект сохранён, Motivelium alpha.2 установлен.":"Проверка остановлена. Причина и выполненные действия — в журнале.";MessageBox.Show(this,(ok?"Обычная установка, запуск из «Пуска», обновление и удаление проверены. Проект и материалы сохранены.":check.Error)+"\n\nПротокол: "+check.ResultFile,"Motivelium",MessageBoxButtons.OK,ok?MessageBoxIcon.Information:MessageBoxIcon.Warning);}));});thread.SetApartmentState(ApartmentState.STA);thread.IsBackground=false;thread.Start();}
 }
 sealed class Checks {
  readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=64*1024*1024};readonly Action<string> progress;readonly string root,app,data,link,runDir;readonly Dictionary<string,object> result=new Dictionary<string,object>();readonly List<object> stages=new List<object>();Process desktop;string origin;Dictionary<string,object> recipe;bool continuing;public volatile bool Cancel;public string Error,ResultFile;
  const string RegPath="Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\Motivelium";
  [DllImport("advapi32.dll",SetLastError=true)]static extern bool GetTokenInformation(IntPtr token,int informationClass,out int information,int size,out int returned);
  static bool IsElevated(){using(var identity=System.Security.Principal.WindowsIdentity.GetCurrent()){int value,length;Require(GetTokenInformation(identity.Token,20,out value,4,out length)&&length==4,"Не удалось определить повышение прав процесса; установка не запускалась.");return value!=0;}}
  static void UnelevatedGuard(bool elevated){Require(!elevated,"Проверка запущена от имени администратора. Закройте её и откройте двойным щелчком из обычного Проводника, без «Запуск от имени администратора». Файлы программы ещё не изменены.");}
  static void KnownRunGuard(Dictionary<string,object> previous,string expectedApp,string expectedData){Require(previous.ContainsKey("success")&&previous["success"] is bool&&(bool)previous["success"]&&previous.ContainsKey("qaInstall")&&previous["qaInstall"] is bool&&!(bool)previous["qaInstall"],"Предыдущий прогон не подтверждает собственную завершённую установку.");Require(SamePath(Str(previous,"appRoot"),expectedApp)&&SamePath(Str(previous,"dataRoot"),expectedData),"Предыдущий прогон относится к другой папке программы или данных.");Require(Str(previous,"registeredVersion")=="0.1.0-alpha.2"&&Str(previous,"upgradeTo")=="0.1.0-alpha.2","Предыдущий прогон относится к другой версии.");}
  public Checks(string directory,Action<string> notify){root=Path.GetFullPath(directory);progress=notify;app=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","Motivelium");data=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Motivelium");link=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"Motivelium","Motivelium.lnk");runDir=Path.Combine(root,"Результаты-Windows","run-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8));ResultFile=Path.Combine(runDir,"result.json");}
  static Dictionary<string,object> Dict(object o){var d=o as Dictionary<string,object>;if(d==null)throw new Exception("Неверная структура протокола.");return d;}
  static string Str(Dictionary<string,object>d,string k){return d.ContainsKey(k)?Convert.ToString(d[k]):"";}
  static string Hash(string p){using(var sha=SHA256.Create())using(var f=File.OpenRead(p))return BitConverter.ToString(sha.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
  static bool SamePath(string a,string b){return String.Equals(Path.GetFullPath(a).TrimEnd('\\','/'),Path.GetFullPath(b).TrimEnd('\\','/'),StringComparison.OrdinalIgnoreCase);}
  static void Require(bool value,string message){if(!value)throw new Exception(message);}
  static string Inside(string parent,string relative){string p=Path.GetFullPath(Path.Combine(parent,relative));Require(p.StartsWith(Path.GetFullPath(parent).TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase),"Путь выходит за каталог проверки.");return p;}
  void Save(){Directory.CreateDirectory(runDir);result["stages"]=stages;result["updatedAt"]=DateTime.UtcNow.ToString("o");string tmp=ResultFile+".tmp";File.WriteAllText(tmp,json.Serialize(result),new UTF8Encoding(false));if(File.Exists(ResultFile))File.Replace(tmp,ResultFile,null);else File.Move(tmp,ResultFile);string latest=Path.Combine(root,"Результаты-Windows","latest.json"),body=json.Serialize(new{resultFile=ResultFile,runId=result["runId"],updatedAt=result["updatedAt"]});tmp=latest+".tmp";File.WriteAllText(tmp,body,new UTF8Encoding(false));if(File.Exists(latest))File.Replace(tmp,latest,null);else File.Move(tmp,latest);}
  void Step(string name,Action action){if(Cancel)throw new OperationCanceledException("Проверка остановлена пользователем между действиями.");progress(name);var begin=DateTime.UtcNow;result["currentStage"]=name;Save();action();stages.Add(new{step=name,passed=true,startedAt=begin.ToString("o"),finishedAt=DateTime.UtcNow.ToString("o")});Save();}
  Dictionary<string,object> ReadJson(string path){return Dict(json.DeserializeObject(File.ReadAllText(path)));}
  Dictionary<string,object> Registered(){using(var b=RegistryKey.OpenBaseKey(RegistryHive.CurrentUser,RegistryView.Registry64))using(var k=b.OpenSubKey(RegPath)){if(k==null)return null;return new Dictionary<string,object>{{"location",Convert.ToString(k.GetValue("InstallLocation"))},{"version",Convert.ToString(k.GetValue("DisplayVersion"))},{"uninstall",Convert.ToString(k.GetValue("UninstallString"))}};}}
  void PermissionCheck(){string probe="Motivelium-Install-Check-"+Guid.NewGuid().ToString("N"),key="Software\\"+probe,file=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),probe+".tmp");try{using(var b=RegistryKey.OpenBaseKey(RegistryHive.CurrentUser,RegistryView.Registry64)){using(var k=b.CreateSubKey(key)){k.SetValue("Check",probe);Require(Convert.ToString(k.GetValue("Check"))==probe,"Не читается проверочная запись реестра.");}b.DeleteSubKeyTree(key);}File.WriteAllText(file,probe);Require(File.ReadAllText(file)==probe,"Не читается проверочный файл меню.");File.Delete(file);}catch(UnauthorizedAccessException){throw new Exception("Windows запретила запись в HKCU или меню «Пуск». Запустите проверочный EXE из Проводника в обычной учётной записи. Установка ещё не запускалась; защитные настройки не менялись.");}}
  void ExistingInstallation(){
   if(Registered()==null){Require(!Directory.Exists(app)||!Directory.EnumerateFileSystemEntries(app).Any(),"В папке программы уже есть файлы. Проверка не будет смешивать установки.");return;}
   Require(recipe.ContainsKey("previousRun"),"Motivelium уже установлен; комплект не содержит квитанции собственного прошлого прогона. Файлы программы не изменены.");
   var receipt=Dict(recipe["previousRun"]);string file=Inside(root,Str(receipt,"file"));Require(Hash(file)==Str(receipt,"sha256"),"Квитанция прошлого прогона повреждена.");var previous=ReadJson(file);KnownRunGuard(previous,app,data);
   Require(Str(previous,"runId")==Str(receipt,"runId"),"Не совпал идентификатор прошлого прогона.");
   Registration("candidate"); // Read-only: exact registered payload, marker and real shortcut.
   string projectId=Str(previous,"projectId");Require(Regex.IsMatch(projectId,"^project-[a-f0-9]{32}$"),"Не распознан проект прошлого прогона.");
   var graph=ReadJson(Path.Combine(data,"projects",projectId,"project.json"));Require(HashJson(graph)==Str(previous,"projectGraphHash"),"Проект прошлого прогона уже изменён; автоматическая повторная проверка не будет менять установку.");
   foreach(var obj in (IEnumerable)graph["assets"]){var asset=Dict(obj);Require(Hash(Inside(Path.Combine(data,"projects",projectId),Str(asset,"path")))==Str(asset,"sha256"),"Изменён ресурс прошлого проверочного проекта.");}
   continuing=true;result["existingVerifiedInstallation"]=true;result["previousRunId"]=Str(previous,"runId");
  }
  Dictionary<string,string> Snapshot(string folder){var map=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);if(!Directory.Exists(folder))return map;foreach(var f in Directory.EnumerateFiles(folder,"*",SearchOption.AllDirectories))map[f.Substring(folder.Length).TrimStart('\\')]=Hash(f);return map;}
  static void EqualSnapshot(Dictionary<string,string>a,Dictionary<string,string>b){Require(a.Count==b.Count,"Изменилось число файлов проектов.");foreach(var p in a)Require(b.ContainsKey(p.Key)&&b[p.Key]==p.Value,"Изменён или потерян файл проекта: "+p.Key);}
  void Install(string key){var item=Dict(recipe[key]);string exe=Inside(root,Str(item,"file"));Require(Hash(exe)==Str(item,"sha256"),"Не совпала SHA-256 установщика "+key+".");RunProcess(exe,"/S");}
  static void RunProcess(string exe,string args){using(var p=Process.Start(new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Path.GetDirectoryName(exe)})){Require(p!=null,"Windows не создала процесс установки.");Require(p.WaitForExit(180000),"Установка не завершилась за 3 минуты. Автоматического завершения процесса нет.");Require(p.ExitCode==0,"Установщик завершился с кодом "+p.ExitCode+". Следующие действия не выполняются.");}}
  void Registration(string key){var item=Dict(recipe[key]);var reg=Registered();Require(reg!=null&&SamePath(Str(reg,"location"),app),"Не совпала настоящая регистрация Windows.");Require(Str(reg,"version")==Str(item,"version"),"Неверная версия в «Установленных приложениях».");var marker=ReadJson(Path.Combine(app,"installed.json"));OrdinaryMarker(marker,Str(item,"version"));var fileInfo=FileVersionInfo.GetVersionInfo(Path.Combine(app,"Motivelium.exe"));Require(fileInfo.ProductVersion==Str(item,"version"),"Версия EXE не совпала с установленным выпуском.");Require(File.Exists(link),"Нет настоящего ярлыка в меню «Пуск».");Require(SamePath(ShortcutTarget(link),Path.Combine(app,"Motivelium.exe")),"Ярлык «Пуска» ведёт в другой каталог.");var manifest=ReadJson(Inside(root,Str(item,"manifest")));int count=0;foreach(var obj in (IEnumerable)manifest["files"]){var f=Dict(obj);string p=Inside(app,Str(f,"path"));Require(File.Exists(p)&&Hash(p)==Str(f,"sha256"),"Не совпал установленный файл: "+Str(f,"path"));count++;}result["verifiedPayloadFiles"]=count;result["registeredVersion"]=Str(reg,"version");}
  static void Wait(Func<bool> ready,string message,int ms){var limit=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<limit){if(ready())return;Thread.Sleep(150);}throw new Exception(message);}
  Dictionary<string,object> Api(string route,string method="GET",object body=null,string token=null){var req=(HttpWebRequest)WebRequest.Create(origin+route);req.Proxy=null;req.Timeout=3000;req.ReadWriteTimeout=3000;req.Method=method;if(token!=null)req.Headers["x-motivelium-token"]=token;if(body!=null){req.ContentType="application/json";byte[] bytes=Encoding.UTF8.GetBytes(json.Serialize(body));req.ContentLength=bytes.Length;using(var s=req.GetRequestStream())s.Write(bytes,0,bytes.Length);}using(var r=req.GetResponse())using(var s=new StreamReader(r.GetResponseStream(),Encoding.UTF8))return Dict(json.DeserializeObject(s.ReadToEnd()));}
  void Launch(){Require(desktop==null,"Предыдущий тестовый экземпляр ещё открыт.");desktop=Process.Start(new ProcessStartInfo(link){UseShellExecute=true,WorkingDirectory=app});Require(desktop!=null,"Запуск ярлыка не вернул процесс приложения.");int startedPid=desktop.Id;Wait(()=>{try{desktop.Refresh();if(desktop.HasExited)throw new Exception("Приложение завершилось сразу после запуска.");var state=ReadJson(Path.Combine(data,"desktop-server.json"));origin="http://127.0.0.1:"+Convert.ToInt32(state["port"]);var health=Api("/api/health");return SamePath(Str(health,"root"),Path.Combine(app,"app"))&&SamePath(Str(health,"dataRoot"),data)&&Convert.ToBoolean(health["studioReady"])&&desktop.MainWindowHandle!=IntPtr.Zero;}catch{return false;}},"Студия из ярлыка не подтвердила готовность и стандартное хранилище.",45000);Require(SamePath(desktop.MainModule.FileName,Path.Combine(app,"Motivelium.exe")),"Ярлык запустил другую программу.");result["startMenuLaunch"]=new{shortcut=link,desktopPid=startedPid,origin=origin,defaultDataRoot=data,ordinaryArguments=true};Thread.Sleep(1500);}
  void CloseOwn(){if(desktop==null)return;desktop.Refresh();if(!desktop.HasExited){Require(SamePath(desktop.MainModule.FileName,Path.Combine(app,"Motivelium.exe")),"Не закрываю неизвестный процесс.");Require(desktop.CloseMainWindow(),"Окно студии не приняло обычное закрытие.");Require(desktop.WaitForExit(20000),"Студия не закрылась. Проверьте её окно; принудительного завершения нет.");}result["lastDesktopExitCode"]=desktop.ExitCode;Require(desktop.ExitCode==0,"Студия завершилась с ошибкой: "+desktop.ExitCode);desktop.Dispose();desktop=null;if(origin!=null)Wait(()=>{try{Api("/api/health");return false;}catch{return true;}},"Собственный сервер не завершился после закрытия приложения.",10000);}
  string ProjectHash(string id){return HashJson(Api("/api/v1/projects/"+id)["project"]);}
  string HashJson(object value){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(json.Serialize(value)))).Replace("-","");}
  public bool Run(){try{Directory.CreateDirectory(runDir);recipe=ReadJson(Path.Combine(root,"windows-check.json"));Require(Str(recipe,"format")=="motivelium-normal-windows-check","Неверный комплект проверки.");result["runId"]=Guid.NewGuid().ToString("N");result["startedAt"]=DateTime.UtcNow.ToString("o");result["qaInstall"]=false;result["appRoot"]=app;result["dataRoot"]=data;result["suiteId"]=recipe["suiteId"];result["verifierVersion"]=2;result["isElevated"]=IsElevated();Save();
   Step("Проверяю, что процесс запущен без повышения прав",()=>{Require(recipe.ContainsKey("requiresUnelevated")&&recipe["requiresUnelevated"] is bool&&(bool)recipe["requiresUnelevated"],"Нужен новый комплект проверки без повышения прав.");UnelevatedGuard((bool)result["isElevated"]);});
