   var original=Snapshot(Path.Combine(data,"projects"));result["originalProjectFiles"]=original.Count;string id=null,projectHash=null,note=Path.Combine(app,"motivelium-install-check-note-"+Str(result,"runId").Substring(0,8)+".txt");Dictionary<string,string> saved=null;
   Step(continuing?"Возвращаю проверенную установку к alpha.1 для повторного прогона":"Устанавливаю Motivelium alpha.1 обычным способом",()=>Install("old"));
   Step("Проверяю регистрацию Windows, версии, файлы и ярлык «Пуска»",()=>Registration("old"));
