   Step("Создаю проверочный проект с изображением и музыкой",()=>{var w=Api("/api/v1/workspace");var created=Api("/api/v1/templates/spectrum/1/projects","POST",new{title="Проверка установки Windows · "+DateTime.Now.ToString("dd.MM.yyyy HH:mm"),requestId="windows-install-"+Guid.NewGuid().ToString("N")},Str(w,"mutationToken"));var p=Dict(created["project"]);id=Str(p,"id");Require(Regex.IsMatch(id,"^project-[a-f0-9]{32}$"),"Неверный идентификатор проверочного проекта.");projectHash=ProjectHash(id);result["projectId"]=id;result["projectGraphHash"]=projectHash;result["testProjectAssets"]=((IEnumerable)p["assets"]).Cast<object>().Count();Require(Convert.ToInt32(result["testProjectAssets"])>=2,"В проект не попали материалы шаблона.");});
   Step("Закрываю только запущенную проверкой студию",CloseOwn);saved=Snapshot(Path.Combine(data,"projects"));result["savedProjectFiles"]=saved.Count;foreach(var x in original)Require(saved.ContainsKey(x.Key)&&saved[x.Key]==x.Value,"Изменился прежний файл проекта.");Require(!File.Exists(note),"В папке есть одноимённый пользовательский файл.");File.WriteAllText(note,"Motivelium: this unknown file must survive uninstall.");
   Step("Обновляю alpha.1 до alpha.2",()=>{Require(Str(Registered(),"version")==Str(Dict(recipe["old"]),"version"),"Версия изменилась посторонним действием.");Install("candidate");Registration("candidate");EqualSnapshot(saved,Snapshot(Path.Combine(data,"projects")));});
   Step("Проверяю запуск и проект после обновления",()=>{Launch();Require(ProjectHash(id)==projectHash,"Проект изменился после обновления.");CloseOwn();EqualSnapshot(saved,Snapshot(Path.Combine(data,"projects")));});
