  }catch(Exception e){Error=e.Message;result["success"]=false;result["error"]=e.ToString();try{CloseOwn();}catch(Exception close){result["closeError"]=close.Message;}try{Save();}catch{}progress(Error);return false;}}
  static void Rejected(Action action,string prefix){bool refused=false;try{action();}catch(Exception e){Require(e.Message.StartsWith(prefix),"Отказал другой guard: "+e.Message);refused=true;}Require(refused,"Проверка не обнаружила нарушение: "+prefix);}
  public static int SelfTest(string output){
   var tests=new List<string>();string dir=Path.Combine(output!=null?Path.GetDirectoryName(Path.GetFullPath(output)):Path.GetTempPath(),"Motivelium-check-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);
   try{
    Rejected(()=>Inside(dir,"../escape"),"Путь выходит за каталог проверки.");tests.Add("path escape rejected");
    var a=new Dictionary<string,string>{{"asset.png","abc"}};var b=new Dictionary<string,string>{{"asset.png","def"}};
    Rejected(()=>EqualSnapshot(a,b),"Изменён или потерян");tests.Add("changed resource rejected");EqualSnapshot(a,new Dictionary<string,string>(a));tests.Add("unchanged data accepted");
    Rejected(()=>OrdinaryMarker(new Dictionary<string,object>{{"format","motivelium-installed"},{"qa",true},{"version","0.1.0-alpha.2"}},"0.1.0-alpha.2"),"Это тестовая /QA");tests.Add("QA install never counts as ordinary");
    OrdinaryMarker(new Dictionary<string,object>{{"format","motivelium-installed"},{"qa",false},{"version","0.1.0-alpha.2"}},"0.1.0-alpha.2");tests.Add("ordinary marker accepted");
    Rejected(()=>UnelevatedGuard(true),"Проверка запущена от имени администратора.");tests.Add("elevated process rejected before installation");UnelevatedGuard(false);tests.Add("unelevated process accepted");
    var previous=new Dictionary<string,object>{{"success",true},{"qaInstall",false},{"appRoot",Path.Combine(dir,"app")},{"dataRoot",Path.Combine(dir,"data")},{"registeredVersion","0.1.0-alpha.2"},{"upgradeTo","0.1.0-alpha.2"}};
    KnownRunGuard(previous,Path.Combine(dir,"app"),Path.Combine(dir,"data"));tests.Add("own completed previous run accepted");
    Rejected(()=>KnownRunGuard(previous,Path.Combine(dir,"other-app"),Path.Combine(dir,"data")),"Предыдущий прогон относится к другой папке");tests.Add("foreign installation rejected");
    previous["qaInstall"]=true;Rejected(()=>KnownRunGuard(previous,Path.Combine(dir,"app"),Path.Combine(dir,"data")),"Предыдущий прогон не подтверждает");tests.Add("QA previous run rejected");previous["qaInstall"]=false;
    previous["success"]=false;Rejected(()=>KnownRunGuard(previous,Path.Combine(dir,"app"),Path.Combine(dir,"data")),"Предыдущий прогон не подтверждает");tests.Add("incomplete previous run rejected");previous["success"]=true;
    previous["registeredVersion"]="other";Rejected(()=>KnownRunGuard(previous,Path.Combine(dir,"app"),Path.Combine(dir,"data")),"Предыдущий прогон относится к другой версии.");tests.Add("different previous version rejected");
    var r=new JavaScriptSerializer().Serialize(new{success=true,tests=tests,observedElevation=IsElevated(),ordinaryWindowsIntegration=false});if(output!=null)File.WriteAllText(output,r);Console.WriteLine(r);return 0;
   }finally{Directory.Delete(dir);}
  }
  static void OrdinaryMarker(Dictionary<string,object> marker,string version){Require(Str(marker,"format")=="motivelium-installed"&&marker.ContainsKey("qa")&&marker["qa"] is bool&&!(bool)marker["qa"],"Это тестовая /QA-установка, обычная проверка не засчитывается.");Require(Str(marker,"version")==version,"Версия установленного маркера неверна.");}
  static string ShortcutTarget(string file){object obj=new ShellLink();try{((System.Runtime.InteropServices.ComTypes.IPersistFile)obj).Load(file,0);var text=new StringBuilder(32768);((IShellLink)obj).GetPath(text,text.Capacity,IntPtr.Zero,0);return text.ToString();}finally{Marshal.FinalReleaseComObject(obj);}}
